#include <functional>
#include <iostream>
#include <optional>
#include <queue>
#include <span>
#include <string>
#include <vector>

// The k-th largest value, or no value when k is outside 1 to the size.
// Keeps the k largest seen so far in a min-heap, so its smallest is the answer.
[[nodiscard]] std::optional<int> kth_largest(std::span<const int> values, std::ptrdiff_t k) {
  if (k < 1 || k > std::ssize(values)) return std::nullopt;
  std::priority_queue<int, std::vector<int>, std::greater<>> smallest_on_top;
  for (const int x : values) {
    smallest_on_top.push(x);
    if (std::ssize(smallest_on_top) > k) smallest_on_top.pop();  // drop the smallest of the k + 1
  }
  return smallest_on_top.top();
}

[[nodiscard]] std::string text(std::optional<int> v) { return v ? std::format("{}", *v) : "none"; }

int main() {
  const std::vector<int> readings{3, 1, 4, 1, 5, 9, 2, 6};
  for (const std::ptrdiff_t k : {1, 3, 8, 9, 0})
    std::cout << std::format("k = {}: {}\n", k, text(kth_largest(readings, k)));
  const std::vector<int> ties{7, 7, 7};
  std::cout << std::format("all equal, k = 2: {}\n", text(kth_largest(ties, 2)));
  std::cout << std::format("empty, k = 1: {}\n", text(kth_largest({}, 1)));
}

