#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out;
  for (const int x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out;
}

int main() {
  std::vector<int> v{5, 3, 8, 2, 4, 9, 1};
  std::cout << std::format("input        {}\n", show(v));
  std::make_heap(v.begin(), v.end());
  std::cout << std::format("make_heap    {}   is_heap {}\n", show(v), std::is_heap(v.begin(), v.end()));

  for (std::ptrdiff_t start = 0, width = 1; start < std::ssize(v); start += width, width *= 2) {
    const std::ptrdiff_t count = std::min(width, std::ssize(v) - start);
    std::cout << std::format("level {}      {}\n", start == 0 ? 0 : (start == 1 ? 1 : 2),
                             show(std::span{v}.subspan(static_cast<std::size_t>(start),
                                                       static_cast<std::size_t>(count))));
  }

  bool ordered = true;
  for (std::ptrdiff_t i = 1; i < std::ssize(v); ++i) ordered = ordered && v[(i - 1) / 2] >= v[i];
  std::cout << std::format("every v[(i-1)/2] >= v[i]: {}\n", ordered);

  v.push_back(7);
  std::cout << std::format("push_back 7  {}   is_heap {}\n", show(v), std::is_heap(v.begin(), v.end()));
  std::push_heap(v.begin(), v.end());
  std::cout << std::format("push_heap    {}   is_heap {}\n", show(v), std::is_heap(v.begin(), v.end()));
  std::pop_heap(v.begin(), v.end());
  std::cout << std::format("pop_heap     {}   largest now at the back\n", show(v));
  v.pop_back();
  std::cout << std::format("pop_back     {}   is_heap {}\n", show(v), std::is_heap(v.begin(), v.end()));
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <random>
#include <span>
#include <string_view>
#include <vector>

// Builds a heap from the whole range at once, and reports the comparisons it took.
[[nodiscard]] std::int64_t by_heapify(std::vector<int> v) {
  std::int64_t comparisons = 0;
  std::make_heap(v.begin(), v.end(), [&comparisons](int a, int b) {
    ++comparisons;
    return a < b;
  });
  return comparisons;
}

// Builds the same heap one element at a time, the way priority_queue::push does.
[[nodiscard]] std::int64_t by_pushes(std::span<const int> values) {
  std::int64_t comparisons = 0;
  const auto less = [&comparisons](int a, int b) {
    ++comparisons;
    return a < b;
  };
  std::vector<int> heap;
  heap.reserve(values.size());
  for (const int x : values) {
    heap.push_back(x);
    std::push_heap(heap.begin(), heap.end(), less);
  }
  return comparisons;
}

void row(std::string_view order, std::span<const int> values) {
  const std::int64_t heapify = by_heapify(std::vector<int>(values.begin(), values.end()));
  const std::int64_t pushes = by_pushes(values);
  std::cout << std::format("{:<24}{:>12}{:>12}{:>10.2f}\n", order, heapify, pushes,
                           static_cast<double>(pushes) / static_cast<double>(heapify));
}

int main() {
  constexpr int n = 4096;
  std::vector<int> ascending(n);
  std::iota(ascending.begin(), ascending.end(), 0);
  std::vector<int> shuffled = ascending;
  std::mt19937 gen{42};
  std::ranges::shuffle(shuffled, gen);
  std::vector<int> descending = ascending;
  std::ranges::reverse(descending);

  std::cout << std::format("{:<24}{:>12}{:>12}{:>10}\n", "4096 values, comparisons", "make_heap", "n pushes",
                           "ratio");
  row("already ascending", ascending);
  row("shuffled", shuffled);
  row("already descending", descending);
  std::cout << std::format("n log2 n = {}, 3n = {}\n", n * 12, 3 * n);
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <queue>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct Task {
  std::string name;
  std::int64_t due_ms = 0;
};

// std::priority_queue calls this "less": comp(a, b) true means a comes out after b.
struct RunsAfter {
  [[nodiscard]] bool operator()(const Task& a, const Task& b) const { return a.due_ms > b.due_ms; }
};

[[nodiscard]] std::string pending(std::span<const Task> tasks) {
  std::string out;
  for (const Task& t : tasks) out += std::format("{}{}@{}", out.empty() ? "" : " ", t.name, t.due_ms);
  return out;
}

int main() {
  const std::vector<Task> arriving{{"calibrate", 900}, {"heartbeat", 100}, {"log-flush", 500},
                                   {"estop-check", 50}, {"map-save", 700}};

  std::priority_queue<Task, std::vector<Task>, RunsAfter> queue;
  for (const Task& t : arriving) queue.push(t);
  std::string order;
  while (!queue.empty()) {
    order += std::format("{}{}", order.empty() ? "" : " ", queue.top().name);
    queue.pop();
  }
  std::cout << std::format("priority_queue  {}\n", order);

  std::vector<Task> heap;
  const RunsAfter runs_after;
  for (const Task& t : arriving) {
    heap.push_back(t);
    std::push_heap(heap.begin(), heap.end(), runs_after);
  }
  std::cout << std::format("the vector      {}\n", pending(heap));
  std::cout << std::format("is a heap: {}, {} tasks pending, next at {} ms\n",
                           std::is_heap(heap.begin(), heap.end(), runs_after), heap.size(), heap.front().due_ms);

  std::string drained;
  while (!heap.empty()) {
    std::pop_heap(heap.begin(), heap.end(), runs_after);  // the earliest moves to the back
    drained += std::format("{}{}", drained.empty() ? "" : " ", heap.back().name);
    heap.pop_back();
  }
  std::cout << std::format("drained         {}\n", drained);

  std::vector<Task> again(arriving.begin(), arriving.end());
  std::make_heap(again.begin(), again.end(), runs_after);
  std::sort_heap(again.begin(), again.end(), runs_after);
  std::cout << std::format("sort_heap       {}\n", pending(again));
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <queue>
#include <span>
#include <string>
#include <unordered_map>
#include <vector>

struct Tally {
  int value = 0;
  std::int64_t count = 0;
};

// priority_queue calls this "less": comp(a, b) true means a leaves the heap after b.
// The rarest value sits on top, and among equal counts the larger value does.
struct Rarer {
  [[nodiscard]] bool operator()(const Tally& a, const Tally& b) const {
    if (a.count != b.count) return a.count > b.count;
    return a.value < b.value;
  }
};

// The k values that appear most often, most frequent first, smaller value first among equal counts.
[[nodiscard]] std::vector<int> top_k_frequent(std::span<const int> readings, std::ptrdiff_t k) {
  if (k < 1) return {};
  std::unordered_map<int, std::int64_t> counts;
  for (const int x : readings) ++counts[x];
  std::priority_queue<Tally, std::vector<Tally>, Rarer> best;
  for (const auto& [value, count] : counts) {
    best.push({.value = value, .count = count});
    if (std::ssize(best) > k) best.pop();  // the rarest of the k + 1 goes
  }
  std::vector<int> out;
  while (!best.empty()) {
    out.push_back(best.top().value);
    best.pop();
  }
  std::ranges::reverse(out);  // the heap gave them rarest first
  return out;
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out;
  for (const int x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

int main() {
  const std::vector<int> readings{1, 1, 1, 2, 2, 3, 3, 4};
  for (const std::ptrdiff_t k : {1, 2, 3, 4, 5, 0})
    std::cout << std::format("k = {}: {}\n", k, show(top_k_frequent(readings, k)));
  std::cout << std::format("empty input, k = 2: {}\n", show(top_k_frequent({}, 2)));
}

#include <cstddef>
#include <format>
#include <iostream>
#include <queue>
#include <span>
#include <string>
#include <vector>

struct Cursor {
  int value = 0;
  std::ptrdiff_t list = 0;  // which list it came from
  std::ptrdiff_t at = 0;    // its position in that list
};

// priority_queue calls this "less": the smallest value has to come out first, so a larger
// value means lower priority. The list index breaks ties, which keeps the merge stable.
struct Later {
  [[nodiscard]] bool operator()(const Cursor& a, const Cursor& b) const {
    if (a.value != b.value) return a.value > b.value;
    return a.list > b.list;
  }
};

[[nodiscard]] std::vector<int> merge_sorted(std::span<const std::vector<int>> lists) {
  std::vector<int> out;
  std::priority_queue<Cursor, std::vector<Cursor>, Later> front;
  std::ptrdiff_t total = 0;
  for (std::ptrdiff_t i = 0; i < std::ssize(lists); ++i) {
    total += std::ssize(lists[static_cast<std::size_t>(i)]);
    if (!lists[static_cast<std::size_t>(i)].empty())
      front.push({.value = lists[static_cast<std::size_t>(i)].front(), .list = i, .at = 0});
  }
  out.reserve(static_cast<std::size_t>(total));
  while (!front.empty()) {
    const Cursor here = front.top();
    front.pop();
    out.push_back(here.value);
    const std::vector<int>& from = lists[static_cast<std::size_t>(here.list)];
    if (here.at + 1 < std::ssize(from))
      front.push({.value = from[static_cast<std::size_t>(here.at + 1)], .list = here.list, .at = here.at + 1});
  }
  return out;
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out;
  for (const int x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out.empty() ? "(none)" : out;
}

int main() {
  const std::vector<std::vector<int>> three{{1, 4, 5}, {1, 3, 4}, {2, 6}};
  std::cout << std::format("three lists       {}\n", show(merge_sorted(three)));
  const std::vector<std::vector<int>> with_empty{{1, 4, 5}, {}, {2, 6}};
  std::cout << std::format("one empty         {}\n", show(merge_sorted(with_empty)));
  const std::vector<std::vector<int>> all_empty{{}, {}, {}};
  std::cout << std::format("all empty         {}\n", show(merge_sorted(all_empty)));
  const std::vector<std::vector<int>> single{{2, 2, 7}};
  std::cout << std::format("one list          {}\n", show(merge_sorted(single)));
  std::cout << std::format("no lists          {}\n", show(merge_sorted({})));
}

#include <algorithm>
#include <format>
#include <functional>
#include <iostream>
#include <queue>
#include <span>
#include <string>
#include <string_view>
#include <vector>

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out;
  for (const int x : v) out += std::format("{}{}", out.empty() ? "" : " ", x);
  return out;
}

template <typename Queue>
[[nodiscard]] std::string drained(Queue queue) {
  std::string out;
  while (!queue.empty()) {
    out += std::format("{}{}", out.empty() ? "" : " ", queue.top());
    queue.pop();
  }
  return out;
}

void row(std::string_view what, std::string_view result) {
  std::cout << std::format("{:<40}{}\n", what, result);
}

int main() {
  const std::vector<int> readings{3, 1, 4, 1, 5, 9, 2, 6};

  std::priority_queue<int> by_default(readings.begin(), readings.end());
  row("priority_queue<int>, popped", drained(by_default));
  std::priority_queue<int, std::vector<int>, std::greater<>> reversed(readings.begin(), readings.end());
  row("the same with std::greater<>, popped", drained(reversed));

  std::vector<int> a = readings;
  std::make_heap(a.begin(), a.end());
  row("make_heap, default: front", std::format("{}", a.front()));
  std::vector<int> b = readings;
  std::make_heap(b.begin(), b.end(), std::greater<>{});
  row("make_heap with std::greater<>: front", std::format("{}", b.front()));

  std::vector<int> c = readings;
  std::ranges::sort(c);
  row("ranges::sort, default", show(c));
  std::vector<int> d = readings;
  std::ranges::sort(d, std::greater<>{});
  row("ranges::sort with std::greater<>", show(d));
}
